import React, { useState } from 'react';
import axios from 'axios';
import './App.css';

function App() {
  const [file, setFile] = useState(null);
  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState('');

  const handleFileChange = (e) => {
    setFile(e.target.files[0]);
    setResult(null);
    setError('');
  };

  const handleScan = async () => {
    if (!file) {
      setError('Please select a document to scan.');
      return;
    }

    setLoading(true);
    setError('');
    setResult(null);

    const formData = new FormData();
    formData.append('file', file);

    try {
      const response = await axios.post('http://localhost:8000/upload', formData, {
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      if (response.data.error) {
        setError(response.data.error);
      } else {
        setResult(response.data);
      }
    } catch (err) {
      setError('Server not responding. Please make sure the backend is running in the terminal.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <>
      <div className="header">
        <h1>Indian Identity & Document Verification</h1>
        <p>AI-Powered Forgery Detection System</p>
      </div>

      <div className="container">
        <p style={{ fontSize: '18px', marginBottom: '30px', color: 'var(--text-muted)' }}>
            Securely verify <strong>Aadhaar, PAN, Voter ID, and Driving Licence</strong> documents in seconds.
        </p>

        <div className="upload-box">
          <div className="upload-icon">📄</div>
          <input type="file" accept=".jpg,.jpeg,.png,.pdf" onChange={handleFileChange} />
          <br />
          <button onClick={handleScan} disabled={loading || !file}>
            {loading ? 'Analyzing...' : 'Start AI Scan'}
          </button>
        </div>

        {loading && (
          <div className="loading">
            <span className="spinner"></span> Analyzing document structure and pixels...
          </div>
        )}

        {error && <div className="error-message">{error}</div>}

        {result && (
          <div className="result">
            <div className={`verdict ${result.verdict === 'Likely Genuine' ? 'genuine' : 'fake'}`}>
              {result.verdict}
            </div>

            <div className="details-grid">
              <div className="detail-card">
                  <p>Detected Document</p>
                  <span>{result.doc_type}</span>
              </div>
              <div className="detail-card">
                  <p>AI Confidence</p>
                  <span>{result.confidence}%</span>
              </div>
            </div>

            <div className="disclaimer">
              ⚠️ <strong>Note:</strong> This system strictly checks document authenticity (tampering/editing) and identity-field consistency. It does NOT determine citizenship or legal status.
            </div>

            <div className="section-box heatmap">
              <h3>🔍 Tampering Check (Error Level Analysis)</h3>
              {result.heatmap_url ? (
                <img src={`http://localhost:8000${result.heatmap_url}`} alt="Forgery Heatmap" />
              ) : (
                <p>No tampering analysis available.</p>
              )}
              <p style={{ fontSize: '13px', color: 'var(--text-muted)', marginTop: '10px' }}>
                Bright areas in the heatmap indicate signs of digital manipulation or Photoshop editing.
              </p>
            </div>

            <div class="section-box">
              <h3>📝 Extracted Text (OCR)</h3>
              <div className="extracted-text">{result.extracted_text || 'No text could be read from this document.'}</div>
            </div>
          </div>
        )}
      </div>
    </>
  );
}

export default App;
